/**
 * Icon data — read from the generated icon modules, never transcribed.
 *
 * Three files in `libs/al-web-components/components/icon/` hold everything this
 * page needs, and all three are AUTO-GENERATED by `icons/icons-config.mjs`:
 *
 *   catalog.ts        `ICON_CATEGORIES` + `catalog` — name, categories, tags.
 *   icon-aliases.ts   `LEGACY_ALIASES` + `SHADOWED_LEGACY_NAMES` — the 37
 *                     deprecated `<al-icon-*>` elements and the one collision.
 *   phosphor/<n>.ts   one glyph each: a viewBox and a `<path>`.
 *
 * WHY THEY ARE PARSED RATHER THAN IMPORTED. They are TypeScript, and Node
 * cannot import a file with type annotations (`readonly AltitudeIconCatalogEntry[]`)
 * without a flag this build does not set. The built package does not close the
 * gap either: `dist/components/icon/` ships `catalog.d.ts` but no `catalog.js`
 * — the catalog is a browse-metadata module deliberately kept out of every
 * application entry point, so nothing bundles it and Vite never emits it.
 * Parsing the source is therefore the only read that works in `astro build`,
 * and it works in a fresh checkout with no `dist/` at all, which the token
 * modules cannot claim.
 *
 * The regexes below are safe in a way a hand-parser normally is not, because
 * every file they read is machine-written with a fixed shape. If the generator
 * changes that shape these throw loudly at build time (see `parseOrThrow`)
 * rather than emitting a page with no icons on it.
 */
import fs from 'node:fs';
import path from 'node:path';
import { repoRoot } from './repo-root.mjs';

const ICON_DIR = path.join(repoRoot(), 'libs', 'al-web-components', 'components', 'icon');

/** Read `file`, apply `re`, and fail the BUILD rather than the page. */
function parseOrThrow(file, re, what) {
  const full = path.join(ICON_DIR, file);
  const match = re.exec(fs.readFileSync(full, 'utf8'));
  if (!match) {
    throw new Error(
      `Could not read ${what} out of ${full}. That file is generated by ` +
        `libs/al-web-components/icons/icons-config.mjs; if its output shape changed, ` +
        `apps/docs/src/lib/icons.mjs has to change with it.`
    );
  }
  return match;
}

/* ------------------------------------------------------------- the catalog */

/** The category vocabulary, in the generator's order — the filter chips. */
export const ICON_CATEGORIES = JSON.parse(
  parseOrThrow('catalog.ts', /export const ICON_CATEGORIES[^=]*=\s*(\[[^\]]*\]);/, 'ICON_CATEGORIES')[1]
);

/** `[{ name, pascalName, categories, tags }]` — one entry per glyph. */
const CATALOG = JSON.parse(
  parseOrThrow('catalog.ts', /export const catalog[^=]*=\s*(\[[\s\S]*?\]);/, 'the icon catalog')[1]
);

/* -------------------------------------------------------------- the glyphs */

/**
 * Every glyph's artwork, keyed by icon name.
 *
 * One `readdirSync` plus 1,512 `readFileSync`s, done ONCE at module scope: ESM
 * caches the module, so the whole set costs the same whether one route renders
 * it or twelve do. Measured at ~210ms of a ~4.5s docs build.
 *
 * A glyph module is exactly:
 *   const glyph: AltitudeIconDef = { v: '0 0 256 256', c: svg`<path d="…"/>` };
 * `v` is the viewBox and `c` the body. The body is READ, not assumed to be a
 * single `<path>` — a few Phosphor glyphs are multi-element — and the viewBox
 * is read rather than hardcoded to `0 0 256 256`, because a future icon set
 * mixed into this directory would silently render at the wrong scale.
 */
const GLYPH_RE = /v:\s*'([^']*)'[\s\S]*?svg`([\s\S]*?)`\s*\}/;

const GLYPHS = new Map();
for (const file of fs.readdirSync(path.join(ICON_DIR, 'phosphor'))) {
  if (!file.endsWith('.ts')) continue;
  const source = fs.readFileSync(path.join(ICON_DIR, 'phosphor', file), 'utf8');
  const match = GLYPH_RE.exec(source);
  if (!match) continue;
  GLYPHS.set(file.slice(0, -3), { viewBox: match[1], body: match[2] });
}

/* --------------------------------------------------------------- the tiles */

/**
 * One row per icon: its metadata joined to its artwork.
 *
 * A catalog entry with no glyph file would render an empty box, which on a page
 * of 1,512 boxes is invisible. It is collected instead, so `MISSING_ARTWORK`
 * can be stated on the page rather than discovered.
 */
export const ICONS = [];
export const MISSING_ARTWORK = [];
for (const entry of CATALOG) {
  const glyph = GLYPHS.get(entry.name);
  if (!glyph) {
    MISSING_ARTWORK.push(entry.name);
    continue;
  }
  ICONS.push({
    name: entry.name,
    categories: entry.categories,
    tags: entry.tags,
    viewBox: glyph.viewBox,
    body: glyph.body,
    /**
     * What the client-side filter matches against: the name plus every tag,
     * one lowercase string. Built here so the filter is a single
     * `String.includes` per tile rather than a loop over a parsed attribute —
     * at 1,512 tiles per keystroke that difference is the difference between a
     * search that feels instant and one that does not.
     */
    haystack: `${entry.name} ${entry.tags.join(' ')}`.toLowerCase(),
  });
}

export const ICON_COUNT = ICONS.length;

/** The bytes of glyph artwork this page inlines — quoted on the page itself. */
export const ARTWORK_BYTES = ICONS.reduce((n, icon) => n + icon.body.length, 0);

/* --------------------------------------------------------- legacy elements */

const LEGACY_MAP = JSON.parse(
  parseOrThrow(
    'icon-aliases.ts',
    /export const LEGACY_ALIASES[^=]*=\s*Object\.freeze\((\{[\s\S]*?\})\);/,
    'LEGACY_ALIASES'
  )[1]
);

/**
 * Legacy names that resolve to a DIFFERENT Phosphor icon than the same string
 * would as a `name=` value. Today that is `list`: `<al-icon-list>` renders the
 * bulleted list, `<al-icon name="list">` renders the hamburger. The alias table
 * is consulted only after a catalog miss, so a legacy name can never shadow a
 * real Phosphor icon — this list is what makes that rule visible rather than
 * implicit.
 */
export const SHADOWED_LEGACY_NAMES = JSON.parse(
  parseOrThrow(
    'icon-aliases.ts',
    /export const SHADOWED_LEGACY_NAMES[^=]*=\s*(\[[^\]]*\]);/,
    'SHADOWED_LEGACY_NAMES'
  )[1]
);

/** The deprecated elements, alphabetical, each with its replacement. */
export const LEGACY_ELEMENTS = Object.keys(LEGACY_MAP)
  .sort()
  .map((legacy) => ({
    legacy,
    element: `al-icon-${legacy}`,
    replacement: LEGACY_MAP[legacy],
    shadowed: SHADOWED_LEGACY_NAMES.includes(legacy),
  }));

/** Icons grouped by category, for the counts beside each filter chip. */
export function categoryCounts() {
  const counts = new Map(ICON_CATEGORIES.map((category) => [category, 0]));
  for (const icon of ICONS) {
    for (const category of icon.categories) {
      counts.set(category, (counts.get(category) ?? 0) + 1);
    }
  }
  return ICON_CATEGORIES.map((category) => ({ category, count: counts.get(category) ?? 0 }));
}

/** How many deprecated elements there are — quoted in prose on both renderings. */
export const LEGACY_COUNT = LEGACY_ELEMENTS.length;
